"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["18638"],{83644(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.publicacoes.tipo_ato.vigencia_sobreposta","status":409,"titulo":"J\xe1 existe uma vers\xe3o viva deste tipo de ato vigente em parte do per\xedodo informado"},"descricao":{"codigo":"uniplus.publicacoes.tipo_ato.vigencia_sobreposta","requisitos":[],"oQueAconteceu":["J\xe1 existe uma vers\xe3o viva do **mesmo c\xf3digo** de tipo de ato cujo per\xedodo\\nde vig\xeancia intercepta, ao menos em parte, o per\xedodo informado.","O c\xf3digo agrupa a s\xe9rie de vers\xf5es de um tipo, e duas vers\xf5es vivas do\\nmesmo c\xf3digo n\xe3o podem valer no mesmo dia \u2014 se pudessem, um ato deste tipo\\nn\xe3o saberia qual delas ler para saber se congela a configura\xe7\xe3o, se tem\\nefeito irrevers\xedvel ou se \xe9 resultado. O sistema garante isso em duas camadas: uma consulta\\npr\xe9via, que d\xe1 a mensagem leg\xedvel no caso comum, e uma restri\xe7\xe3o de\\nexclus\xe3o no pr\xf3prio banco, que fecha a corrida entre duas requisi\xe7\xf5es\\nconcorrentes tentando reservar o mesmo per\xedodo ao mesmo tempo. \xc9 por isso\\nque este \xe9 conflito (**409**), n\xe3o invariante de formato (422): o corpo do pedido\\nem si est\xe1 coerente \u2014 o que n\xe3o cabe \xe9 junto do que j\xe1 existe gravado.","Na atualiza\xe7\xe3o, esta confer\xeancia s\xf3 roda quando o c\xf3digo ou o per\xedodo de\\nvig\xeancia mudam; alterar nome ou atributos de consequ\xeancia n\xe3o pode gerar\\nconflito."],"comoResolver":["Ajuste o per\xedodo de vig\xeancia para n\xe3o interceptar nenhuma vers\xe3o viva j\xe1\\ncadastrada com o mesmo c\xf3digo \u2014 normalmente isso significa encerrar a\\nvers\xe3o anterior (dar-lhe um fim) antes de abrir a nova, ou escolher um\\nin\xedcio posterior ao fim da vers\xe3o vigente. Consulte a s\xe9rie de vers\xf5es do\\nc\xf3digo para ver quais per\xedodos j\xe1 est\xe3o ocupados."],"ondeAparece":["Cria\xe7\xe3o de tipo de ato","Atualiza\xe7\xe3o de tipo de ato, quando o c\xf3digo ou o per\xedodo de vig\xeancia muda"]},"modulo":{"id":"publicacoes","nome":"Publica\xe7\xf5es","assunto":"Tipo ato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);